mapper.update:
UPDATE tb_code_group
SET group_nm = #{groupNm},
    description = #{description},
    use_yn = #{useYn}
WHERE group_cd = #{groupCd}
  AND date_trunc('second', mod_dt) = date_trunc('second', #{modDt}::timestamp)

mapper.select:
SELECT group_cd, code, code_nm, sort_ord, description, use_yn, mod_dt
FROM tb_code WHERE group_cd = #{groupCd}
ORDER BY sort_ord, code
